<script setup lang="ts">
const { filaments, printers, products, marketplaces, settings, listCalculatorSimulations, createCalculatorSimulation } = useAppData()
const { notify } = useUi()
const route = useRoute()
import { calculatePricing } from '../../utils/pricing.js'
const round2 = (value: number) => Math.round((Number(value || 0) + Number.EPSILON) * 100) / 100
const productId = ref(''), filamentId = ref(''), printerId = ref('')
const simulationName = ref('')
const advancedCostsOpen = ref(false)
const machineCostsOpen = ref(false)
const priceKg = ref(0), weight = ref(0), wasteGrams = ref(0), failurePercent = ref(0), hours = ref(0), minutes = ref(0), quantity = ref(1)
const energyEnabled = ref(true), energyRate = ref(0), watts = ref(0)
const marketplaceSource = ref('manual'), marketplaceName = ref('')
const packaging = ref(0), materials = ref(0), labor = ref(0), setupMinutes = ref(0), postProcessingMinutes = ref(0), packagingMinutes = ref(0), laborRatePerHour = ref(0), otherCosts = ref(0), printerPurchasePrice = ref(0), printerLifespanHours = ref(5000), machineMaintenancePerHour = ref(0), minimumPrice = ref(0), marketplaceFee = ref(0), taxPercent = ref(0), desiredMargin = ref(40)
const salePrice = ref(0)
const errors = reactive<Record<string, string>>({})
const simulations = ref<any[]>([])
const historyLoading = ref(false)
const selectedProduct = computed(() => products.value.find(product => String(product.id || '') === productId.value))
const preferences = computed(() => (settings.value?.preferences || {}) as Record<string, unknown>)
const fixedCostPerUnit = computed(() => { const fixed = Number(preferences.value.monthlyFixedCost || 0); const planned = Number(preferences.value.plannedMonthlyUnits || 0); return planned > 0 ? fixed / planned : 0 })
const selectedFilament = computed(() => filaments.value.find(filament => String(filament.id || '') === filamentId.value))
const selectedPrinter = computed(() => printers.value.find(printer => String(printer.id || '') === printerId.value))
const selectedMarketplace = computed(() => marketplaces.value.find(marketplace => marketplace.name === marketplaceName.value))
const channelFee = computed(() => selectedMarketplace.value ? Number(selectedMarketplace.value.commission || 0) + Number(selectedMarketplace.value.financial || 0) + Number(selectedMarketplace.value.ads || 0) + Number(selectedMarketplace.value.others || 0) : 0)
const effectiveMarketplaceFee = computed(() => marketplaceSource.value === 'channel' ? channelFee.value : Number(marketplaceFee.value || 0))
const effectiveMarketplaceFixedFee = computed(() => marketplaceSource.value === 'channel' ? Number(selectedMarketplace.value?.fixed || 0) : 0)
const batchQuantity = computed(() => Math.max(1, Math.floor(Number(quantity.value || 1))))
const batchDurationMinutes = computed(() => Math.max(0, Number(hours.value || 0) * 60 + Number(minutes.value || 0)))
const unitDurationMinutes = computed(() => batchDurationMinutes.value / batchQuantity.value)
const pricing = computed(() => calculatePricing({ pricePerKg: priceKg.value, weight: weight.value, wastePercent: weight.value > 0 ? Number(wasteGrams.value || 0) / Number(weight.value) * 100 : 0, failurePercent: failurePercent.value, hours: 0, minutes: unitDurationMinutes.value, energyEnabled: energyEnabled.value, energyRate: energyRate.value, watts: watts.value, fixedCostPerUnit: fixedCostPerUnit.value, packaging: packaging.value, materials: materials.value, labor: labor.value, setupMinutes: Number(setupMinutes.value || 0) / batchQuantity.value, postProcessingMinutes: Number(postProcessingMinutes.value || 0) / batchQuantity.value, packagingMinutes: packagingMinutes.value, laborRatePerHour: laborRatePerHour.value, otherCosts: otherCosts.value, printerPurchasePrice: printerPurchasePrice.value, printerLifespanHours: printerLifespanHours.value, machineMaintenancePerHour: machineMaintenancePerHour.value, quantity: batchQuantity.value, minimumPrice: minimumPrice.value, marketplaceFee: effectiveMarketplaceFee.value, marketplaceFixedFee: effectiveMarketplaceFixedFee.value, taxPercent: taxPercent.value, desiredMargin: desiredMargin.value, salePrice: salePrice.value }))
const duration = computed(() => pricing.value.durationMinutes / 60), effectiveWeight = computed(() => pricing.value.effectiveWeight), costGram = computed(() => Math.max(0, Number(priceKg.value || 0)) / 1000), filamentCost = computed(() => pricing.value.materialCost), energyCost = computed(() => pricing.value.energyCost), baseCost = computed(() => pricing.value.baseCost), feeRate = computed(() => pricing.value.feeRate), priceDenominator = computed(() => pricing.value.denominator), suggestedPrice = computed(() => pricing.value.suggestedPrice), feeCost = computed(() => pricing.value.feeCost), totalCost = computed(() => pricing.value.totalCost), estimatedProfit = computed(() => pricing.value.profit), actualMargin = computed(() => pricing.value.margin), batchTotalCost = computed(() => pricing.value.batchTotalCost), batchProfit = computed(() => pricing.value.batchProfit)
const appliedSalePrice = computed(() => pricing.value.salePrice)
const productionCost = computed(() => pricing.value.riskBaseCost)
const manualSalePrice = computed(() => Number(salePrice.value || 0) > 0)
const additionalCostBreakdown = computed(() => Math.max(0, Number((pricing.value.additionalCost - pricing.value.machineCost - pricing.value.laborCost - pricing.value.failureCost).toFixed(2))))
const hasAdvancedCosts = computed(() => packaging.value > 0 || materials.value > 0 || labor.value > 0 || otherCosts.value > 0 || setupMinutes.value > 0 || postProcessingMinutes.value > 0 || packagingMinutes.value > 0 || laborRatePerHour.value > 0)
const hasMachineCosts = computed(() => printerPurchasePrice.value > 0 || machineMaintenancePerHour.value > 0)
const desiredMarginMax = computed(() => Math.max(0, Math.floor(99 - feeRate.value * 100)))
const updateDesiredMargin = (value: unknown) => { const parsed = Number(String(value ?? '').replace(',', '.')); if (!Number.isFinite(parsed)) return; desiredMargin.value = Math.min(desiredMarginMax.value, Math.max(0, Math.round(parsed))) }
const updateDesiredMarginInput = (event: Event) => updateDesiredMargin((event.target as HTMLInputElement).value)
const syncDesiredMarginInput = (event: Event) => { (event.target as HTMLInputElement).value = Number(desiredMargin.value).toFixed(0) }
const viability = computed(() => priceDenominator.value <= 0 ? { title: 'Parametros inviaveis', text: 'A margem desejada somada as taxas precisa ser menor que 100%.', state: 'bad' } : actualMargin.value >= 40 ? { title: 'Peca viavel', text: 'O preco cobre os custos completos, as taxas e a margem desejada.', state: 'good' } : actualMargin.value >= 20 ? { title: 'Margem de atencao', text: 'A simulacao e possivel, mas revise os custos antes de vender.', state: 'warn' } : { title: 'Margem baixa', text: 'Revise o preco ou os custos para proteger a rentabilidade.', state: 'bad' })
const clearErrors = () => Object.keys(errors).forEach(key => delete errors[key])
const validate = () => { clearErrors(); if (priceKg.value < 0) errors.priceKg = 'Informe um preco valido.'; if (weight.value <= 0) errors.weight = 'Informe o peso da peca.'; if (hours.value < 0 || minutes.value < 0 || minutes.value > 59) errors.duration = 'Informe um tempo valido.'; if (quantity.value < 1 || !Number.isFinite(Number(quantity.value))) errors.quantity = 'Informe pelo menos 1 unidade.'; if (energyEnabled.value && (energyRate.value < 0 || watts.value < 0)) errors.energy = 'Informe energia e potencia validas.'; if (wasteGrams.value < 0) errors.wasteGrams = 'A perda nao pode ser negativa.'; if (failurePercent.value < 0 || failurePercent.value > 95) errors.failure = 'A taxa de falha deve ficar entre 0% e 95%.'; if (printerPurchasePrice.value < 0 || printerLifespanHours.value < 0 || machineMaintenancePerHour.value < 0) errors.machine = 'Informe custos de maquina validos.'; if (marketplaceSource.value === 'channel' && !selectedMarketplace.value) errors.fees = 'Selecione um canal cadastrado.'; if (marketplaceSource.value === 'manual' && marketplaceFee.value < 0 || taxPercent.value < 0) errors.fees = 'Informe taxas validas.'; if (desiredMargin.value < 0 || desiredMargin.value >= 100 - feeRate.value * 100) errors.margin = 'A margem deve deixar espaco para as taxas.'; return !Object.keys(errors).length }
const configuredEnergyRate = computed(() => Number(settings.value?.kwh || 0))
const selectedPrinterEnergyRate = computed(() => {
  const printer = selectedPrinter.value as any
  return Number(printer?.energyRate || printer?.kwh || printer?.energyKwh || printer?.kwhCost || 0)
})
const syncSelectedPrinterEnergy = () => {
  const printerPower = Number(selectedPrinter.value?.power || 0)
  if (printerPower <= 0) return
  watts.value = printerPower
  energyEnabled.value = true
  const registeredEnergyRate = selectedPrinterEnergyRate.value || configuredEnergyRate.value
  if (registeredEnergyRate > 0) energyRate.value = registeredEnergyRate
}
const applyProduct = (product: any) => { if (!product) return; const breakdown = product.costBreakdown || {}; weight.value = Number(product.weight || weight.value); const time = String(product.time || '').match(/(\d+(?:[.,]\d+)?)\s*h(?:\s*(\d+(?:[.,]\d+)?)\s*m)?/i); if (time) { hours.value = Number(time[1].replace(',', '.')); minutes.value = Number((time[2] || 0).replace(',', '.')) }; quantity.value = Number(breakdown.unitsPerRun ?? breakdown.batchQuantity ?? breakdown.quantity ?? 1); printerId.value = String(product.printerId || ''); filamentId.value = String(product.filamentId || ''); wasteGrams.value = Number(breakdown.wasteGrams ?? (Number(product.weight || weight.value) * Number(breakdown.wastePercent || 0) / 100)); failurePercent.value = Number(breakdown.failurePercent || 0); packaging.value = Number(product.packaging || 0); materials.value = Number(product.materials || 0); labor.value = Number(product.labor || 0); setupMinutes.value = Number(breakdown.setupMinutes || 0); postProcessingMinutes.value = Number(breakdown.postProcessingMinutes || 0); packagingMinutes.value = Number(breakdown.packagingMinutes || 0); laborRatePerHour.value = Number(breakdown.laborRatePerHour || 0); printerPurchasePrice.value = Number(breakdown.printerPurchasePrice || 0); printerLifespanHours.value = Number(breakdown.printerLifespanHours || 5000); machineMaintenancePerHour.value = Number(breakdown.machineMaintenancePerHour || 0); minimumPrice.value = Number(breakdown.minimumPrice || 0); otherCosts.value = Number(breakdown.otherCosts || 0); marketplaceFee.value = Number(product.marketplaceFee || 0); desiredMargin.value = Number(product.desiredMargin || preferences.value.defaultMargin || 40) }
watch(productId, value => applyProduct(products.value.find(product => String(product.id || '') === value)))
watch(filamentId, value => { const filament = filaments.value.find(item => String(item.id || '') === value); if (filament?.initial) priceKg.value = round2(Number(filament.cost || 0) / Number(filament.initial) * 1000) })
watch([printerId, printers, configuredEnergyRate, selectedPrinterEnergyRate], syncSelectedPrinterEnergy, { immediate: true })
watch(() => settings.value, value => { if (!value) return; if (desiredMargin.value === 40) desiredMargin.value = Number(preferences.value.defaultMargin || 40); syncSelectedPrinterEnergy() }, { immediate: true })
watch(desiredMarginMax, max => { if (desiredMargin.value > max) desiredMargin.value = max })
const simulation = computed(() => ({ productId: productId.value, productName: selectedProduct.value?.name || '', filamentId: filamentId.value, printerId: printerId.value, priceKg: priceKg.value, weight: weight.value, wasteGrams: wasteGrams.value, wastePercent: weight.value > 0 ? Number(wasteGrams.value || 0) / Number(weight.value) * 100 : 0, failurePercent: failurePercent.value, hours: hours.value, minutes: minutes.value, batchDurationMinutes: batchDurationMinutes.value, unitDurationMinutes: unitDurationMinutes.value, quantity: batchQuantity.value, unitsPerRun: batchQuantity.value, batchQuantity: batchQuantity.value, energyEnabled: energyEnabled.value, energyRate: energyRate.value, watts: watts.value, packaging: packaging.value, materials: materials.value, labor: labor.value, setupMinutes: setupMinutes.value, postProcessingMinutes: postProcessingMinutes.value, packagingMinutes: packagingMinutes.value, laborRatePerHour: laborRatePerHour.value, printerPurchasePrice: printerPurchasePrice.value, printerLifespanHours: printerLifespanHours.value, machineMaintenancePerHour: machineMaintenancePerHour.value, minimumPrice: minimumPrice.value, otherCosts: otherCosts.value, marketplaceSource: marketplaceSource.value, marketplaceName: marketplaceName.value, marketplaceFee: effectiveMarketplaceFee.value, marketplaceFixedFee: effectiveMarketplaceFixedFee.value, taxPercent: taxPercent.value, desiredMargin: desiredMargin.value, baseCost: baseCost.value, totalCost: totalCost.value, batchTotalCost: batchTotalCost.value, suggestedPrice: suggestedPrice.value, profit: estimatedProfit.value, batchProfit: batchProfit.value, margin: actualMargin.value, savedAt: new Date().toISOString() }))
const saveSimulation = async () => {
  if (!validate()) return notify('Revise os campos destacados.', 'info')
  try {
    const saved = await createCalculatorSimulation({ name: simulationName.value.trim() || selectedProduct.value?.name || 'Simulacao sem nome', pricePerKg: priceKg.value, weight: weight.value, durationMinutes: Math.round(batchDurationMinutes.value), energyEnabled: energyEnabled.value, energyRate: energyRate.value, watts: watts.value, margin: desiredMargin.value, directCost: totalCost.value, suggestedPrice: suggestedPrice.value, snapshot: simulation.value })
    simulations.value = [saved, ...simulations.value.filter(item => item.id !== saved.id)].slice(0, 20)
    if (import.meta.client) sessionStorage.setItem('printflow-calculator-simulation', JSON.stringify(simulation.value))
    notify('Simulacao salva no historico.')
  } catch (error: any) { notify(error?.data?.error || error?.message || 'Nao foi possivel salvar a simulacao.', 'info') }
}
const loadSimulation = (item: any) => {
  const draft = item?.snapshot || item
  simulationName.value = item?.name || ''
  productId.value = draft.productId || ''
  filamentId.value = draft.filamentId || ''
  printerId.value = draft.printerId || ''
  priceKg.value = Number(draft.priceKg ?? item.pricePerKg ?? priceKg.value); weight.value = Number(draft.weight ?? item.weight ?? weight.value); wasteGrams.value = Number(draft.wasteGrams ?? (Number(draft.weight ?? item.weight ?? weight.value) * Number(draft.wastePercent || 0) / 100)); failurePercent.value = Number(draft.failurePercent || 0); quantity.value = Number(draft.unitsPerRun ?? draft.batchQuantity ?? draft.quantity ?? 1)
  const loadedDurationMinutes = Number(draft.batchDurationMinutes ?? item.durationMinutes ?? 0)
  hours.value = Math.floor(Number(draft.hours ?? loadedDurationMinutes / 60 ?? hours.value)); minutes.value = Number(draft.minutes ?? loadedDurationMinutes % 60)
  energyEnabled.value = draft.energyEnabled !== false; energyRate.value = Number(draft.energyRate ?? item.energyRate ?? energyRate.value); watts.value = Number(draft.watts ?? item.watts ?? watts.value)
  packaging.value = Number(draft.packaging || 0); materials.value = Number(draft.materials || 0); labor.value = Number(draft.labor || 0); setupMinutes.value = Number(draft.setupMinutes || 0); postProcessingMinutes.value = Number(draft.postProcessingMinutes || 0); packagingMinutes.value = Number(draft.packagingMinutes || 0); laborRatePerHour.value = Number(draft.laborRatePerHour || 0); printerPurchasePrice.value = Number(draft.printerPurchasePrice || 0); printerLifespanHours.value = Number(draft.printerLifespanHours || 5000); machineMaintenancePerHour.value = Number(draft.machineMaintenancePerHour || 0); minimumPrice.value = Number(draft.minimumPrice || 0); otherCosts.value = Number(draft.otherCosts || 0); marketplaceSource.value = draft.marketplaceSource || 'manual'; marketplaceName.value = draft.marketplaceName || ''; marketplaceFee.value = Number(draft.marketplaceFee || 0); taxPercent.value = Number(draft.taxPercent || 0); desiredMargin.value = Number(draft.desiredMargin ?? item.margin ?? desiredMargin.value)
}
const createProduct = () => { if (!validate()) return notify('Revise os campos destacados.', 'info'); if (import.meta.client) sessionStorage.setItem('printflow-calculator-draft', JSON.stringify(simulation.value)); navigateTo('/produtos/novo?from=calculator') }
onMounted(async () => { const queryProduct = String(route.query.productId || ''); if (queryProduct) productId.value = queryProduct; historyLoading.value = true; try { simulations.value = await listCalculatorSimulations() } catch { simulations.value = [] } finally { historyLoading.value = false } })
</script>
<template>
  <div>
    <PageHeader title="Calculadora 3D" subtitle="Calcule o custo completo e o preco minimo rentavel de uma peca." icon="calculator"/>

    <div class="calculator-layout">
      <div>
        <div class="form-card calculator-step">
          <div class="calculator-step__head"><span>1</span><div><h2>Base da simulacao</h2><p>Use um produto salvo ou preencha manualmente.</p></div></div>
          <div class="form-grid">
            <div class="field col-12"><label>Nome da simulacao</label><input v-model="simulationName" maxlength="160" placeholder="Ex.: Vaso grande PLA preto"></div>
            <div class="field col-12"><label>Produto cadastrado (opcional)</label><select v-model="productId"><option value="">Simulacao manual</option><option v-for="product in products" :key="product.id" :value="product.id">{{product.name}} - {{product.sku}}</option></select><small>Ao selecionar, receita e custos conhecidos sao preenchidos.</small></div>
            <div class="field col-6"><label>Filamento</label><select v-model="filamentId"><option value="">Informar preco manualmente</option><option v-for="filament in filaments" :key="filament.id" :value="filament.id">{{filament.name}} - {{filament.material}}</option></select></div>
            <div class="field col-6"><label>Impressora</label><select v-model="printerId"><option value="">Informar potencia manualmente</option><option v-for="printer in printers" :key="printer.id" :value="printer.id">{{printer.name}} - {{printer.power}} W</option></select></div>
          </div>
        </div>

        <div class="form-card calculator-step">
          <div class="calculator-step__head"><span>2</span><div><h2>Material, lote e tempo</h2><p>Informe os dados que normalmente saem do fatiador.</p></div></div>
          <div class="form-grid">
            <div class="field col-4" :class="{'field--error':errors.priceKg}"><label>Preco do filamento por kg (R$)</label><input v-model.number="priceKg" type="number" min="0" step=".01"><small>Informe o valor equivalente a 1 kg de filamento.</small><small v-if="errors.priceKg" class="field__error">{{errors.priceKg}}</small></div>
            <div class="field col-4" :class="{'field--error':errors.weight}"><label>Peso por peca (g)</label><input v-model.number="weight" type="number" min="0" step=".1"><small v-if="errors.weight" class="field__error">{{errors.weight}}</small></div>
            <div class="field col-4" :class="{'field--error':errors.wasteGrams}"><label>Perda de material (g)</label><input v-model.number="wasteGrams" type="number" min="0" step=".1"><small v-if="errors.wasteGrams" class="field__error">{{errors.wasteGrams}}</small></div>
            <div class="field col-4" :class="{'field--error':errors.quantity}"><label>Unidades por execucao</label><input v-model.number="quantity" type="number" min="1" step="1"><small>Produtos completos produzidos pelo mesmo arquivo.</small><small v-if="errors.quantity" class="field__error">{{errors.quantity}}</small></div>
            <div class="stat-box col-12"><small>Custo por grama</small><strong>{{formatCurrency(costGram)}}</strong><small>Material considerado por peca: {{effectiveWeight.toFixed(1)}} g</small></div>
          </div>
        </div>

        <div class="form-card calculator-step">
          <div class="calculator-step__head calculator-step__head--plain"><span><UiIcon name="clock"/></span><div><h2>Tempo do lote e energia</h2></div></div>
          <div class="form-grid">
            <div class="field col-3" :class="{'field--error':errors.duration}"><label>Tempo do lote (horas)</label><input v-model.number="hours" type="number" min="0"></div>
            <div class="field col-3"><label>Minutos do lote</label><input v-model.number="minutes" type="number" min="0" max="59"><small v-if="errors.duration" class="field__error">{{errors.duration}}</small></div>
            <div class="field col-6"><label>Considerar energia?</label><div class="switch-row"><button type="button" class="switch" :class="{active:energyEnabled}" @click="energyEnabled=!energyEnabled"/></div></div>
            <div class="field col-6" :class="{'field--error':errors.energy}"><label>Custo do kWh (R$)</label><input v-model.number="energyRate" type="number" min="0" step=".01"></div>
            <div class="field col-6"><label>Potencia media (W)</label><input v-model.number="watts" type="number" min="0"><small v-if="errors.energy" class="field__error">{{errors.energy}}</small></div>
            <div class="info-note col-12"><UiIcon name="info"/>O tempo informado e do lote inteiro. A calculadora divide energia, maquina e etapas compartilhadas pelo numero de pecas.</div>
            <div class="field col-6"><label>Fonte das taxas</label><select v-model="marketplaceSource"><option value="manual">Informar manualmente</option><option value="channel" :disabled="!marketplaces.length">Canal cadastrado</option></select></div>
            <div v-if="marketplaceSource === 'channel'" class="field col-6"><label>Canal</label><select v-model="marketplaceName"><option value="">Selecione um canal</option><option v-for="marketplace in marketplaces" :key="marketplace.id || marketplace.name" :value="marketplace.name">{{marketplace.name}}</option></select><small>{{effectiveMarketplaceFee.toFixed(1)}}% + {{formatCurrency(effectiveMarketplaceFixedFee)}} fixos</small></div>
            <div v-else class="field col-6"><label>Taxas marketplace (%)</label><input v-model.number="marketplaceFee" type="number" min="0" step=".1"></div>
            <div class="field col-4"><label>Impostos (%)</label><input v-model.number="taxPercent" type="number" min="0" step=".1"><small v-if="errors.fees" class="field__error">{{errors.fees}}</small></div>
            <div class="field col-4" :class="{'field--error':errors.failure}"><label>Reserva para falhas (%)</label><input v-model.number="failurePercent" type="number" min="0" max="95" step=".1"><small v-if="errors.failure" class="field__error">{{errors.failure}}</small></div>
            <div class="field col-4" :class="{'field--error':errors.salePrice}"><label>Preco praticado (R$)</label><input v-model.number="salePrice" type="number" min="0" step=".01" placeholder="Usar sugerido"><small>Zero usa o preco sugerido.</small><small v-if="errors.salePrice" class="field__error">{{errors.salePrice}}</small></div>
          </div>
        </div>

        <details class="form-card calculator-disclosure" :open="advancedCostsOpen || hasAdvancedCosts" @toggle="advancedCostsOpen = ($event.target as HTMLDetailsElement).open">
          <summary><span><UiIcon name="money"/>Custos opcionais</span><small>Embalagem, materiais e mao de obra manual</small></summary>
          <div class="form-grid">
            <div class="field col-3"><label>Embalagem (R$)</label><input v-model.number="packaging" type="number" min="0" step=".01"></div>
            <div class="field col-3"><label>Materiais (R$)</label><input v-model.number="materials" type="number" min="0" step=".01"></div>
            <div class="field col-3"><label>Mao de obra manual (R$)</label><input v-model.number="labor" type="number" min="0" step=".01"></div>
            <div class="field col-3"><label>Outros custos (R$)</label><input v-model.number="otherCosts" type="number" min="0" step=".01"></div>
            <div class="field col-3"><label>Preparacao (min)</label><input v-model.number="setupMinutes" type="number" min="0"></div>
            <div class="field col-3"><label>Pos-processamento (min)</label><input v-model.number="postProcessingMinutes" type="number" min="0"></div>
            <div class="field col-3"><label>Embalagem (min)</label><input v-model.number="packagingMinutes" type="number" min="0"></div>
            <div class="field col-3"><label>Valor da hora (R$)</label><input v-model.number="laborRatePerHour" type="number" min="0" step=".01"></div>
          </div>
        </details>

        <details class="form-card calculator-disclosure" :open="machineCostsOpen || hasMachineCosts" @toggle="machineCostsOpen = ($event.target as HTMLDetailsElement).open">
          <summary><span><UiIcon name="printer"/>Maquina e depreciacao</span><small>Use quando quiser incluir desgaste e manutencao</small></summary>
          <div class="form-grid">
            <div class="field col-4"><label>Valor da impressora (R$)</label><input v-model.number="printerPurchasePrice" type="number" min="0" step=".01"></div>
            <div class="field col-4"><label>Vida util estimada (horas)</label><input v-model.number="printerLifespanHours" type="number" min="0" step="1"><small v-if="errors.machine" class="field__error">{{errors.machine}}</small></div>
            <div class="field col-4"><label>Manutencao por hora (R$)</label><input v-model.number="machineMaintenancePerHour" type="number" min="0" step=".01"></div>
          </div>
        </details>

        <div class="calculator-actions"><button class="btn btn--primary" @click="validate() ? notify('Simulacao validada com sucesso.') : notify('Revise os campos destacados.', 'info')"><UiIcon name="calculator"/>Validar calculo</button><button class="btn" @click="saveSimulation"><UiIcon name="save"/>Salvar no historico</button></div>
        <div class="form-card simulation-history"><h2 class="form-card__title"><UiIcon name="clock"/>Historico de simulacoes</h2><div v-if="historyLoading" class="empty-state">Carregando historico...</div><div v-else-if="!simulations.length" class="empty-state"><div><h3>Nenhuma simulacao salva</h3><p>Salve uma simulacao para recupera-la depois.</p></div></div><div v-else><button v-for="item in simulations" :key="item.id" type="button" class="simulation-history__row" @click="loadSimulation(item)"><span><strong>{{item.name}}</strong><small>{{new Date(item.createdAt).toLocaleString('pt-BR')}}</small></span><span><strong>{{formatCurrency(item.suggestedPrice)}}</strong><small>{{Number(item.margin).toFixed(1)}}% de margem</small></span></button></div></div>
      </div>

      <aside class="calculator-results">
        <div class="calculator-results__head"><UiIcon name="trend" :size="34"/><div><h2>Resultado da simulacao</h2><p>Preco sugerido, margem e composicao do custo.</p></div></div>
        <div class="result-grid"><div class="result-card result-card--highlight"><div class="result-card__label"><UiIcon name="tag"/>Preco sugerido</div><strong>{{formatCurrency(suggestedPrice)}}</strong><small>Custo: {{formatCurrency(totalCost)}} &bull; Lucro: {{formatCurrency(estimatedProfit)}} &bull; Margem: {{actualMargin.toFixed(1)}}%</small><small v-if="manualSalePrice">Preco praticado: {{formatCurrency(appliedSalePrice)}}</small></div><div class="result-card"><div class="result-card__label"><UiIcon name="spool"/>Material</div><strong>{{formatCurrency(filamentCost)}}</strong><small>{{effectiveWeight.toFixed(1)}} g x {{formatCurrency(costGram)}}/g</small></div><div class="result-card"><div class="result-card__label"><UiIcon name="bolt"/>Energia</div><strong>{{formatCurrency(energyCost)}}</strong><small>{{energyEnabled ? `${(watts / 1000 * duration).toFixed(2)} kWh x ${formatCurrency(energyRate)}` : 'Nao considerada'}}</small></div><div v-if="pricing.machineCost > 0" class="result-card"><div class="result-card__label"><UiIcon name="printer"/>Maquina</div><strong>{{formatCurrency(pricing.machineCost)}}</strong><small>{{formatCurrency(pricing.machineHourlyCost)}}/h</small></div><div v-if="pricing.laborCost > 0" class="result-card"><div class="result-card__label"><UiIcon name="clock"/>Mao de obra</div><strong>{{formatCurrency(pricing.laborCost)}}</strong><small>{{pricing.laborMinutes}} min + valor manual</small></div><div v-if="pricing.failureCost > 0" class="result-card"><div class="result-card__label"><UiIcon name="alert"/>Reserva de falhas</div><strong>{{formatCurrency(pricing.failureCost)}}</strong><small>{{failurePercent}}% sobre custos de producao</small></div><div v-if="additionalCostBreakdown > 0" class="result-card"><div class="result-card__label"><UiIcon name="money"/>Custos adicionais</div><strong>{{formatCurrency(additionalCostBreakdown)}}</strong><small>Fixos, embalagem, materiais e outros</small></div><div v-if="feeCost > 0" class="result-card"><div class="result-card__label"><UiIcon name="wallet"/>Taxas e impostos</div><strong>{{formatCurrency(feeCost)}}</strong><small>{{(feeRate * 100).toFixed(1)}}% + fixos do canal</small></div><div v-if="manualSalePrice" class="result-card result-card--purple"><div class="result-card__label"><UiIcon name="percent"/>Margem no preco praticado</div><strong>{{actualMargin.toFixed(1)}}%</strong><small>No preco de {{formatCurrency(appliedSalePrice)}}</small></div></div>
        <div class="margin-control"><div class="margin-control__head"><div><strong>Margem desejada</strong><small>Ajuste a margem para atualizar o preco automaticamente.</small></div><label class="margin-control__value"><input :value="Number(desiredMargin).toFixed(0)" type="number" min="0" :max="desiredMarginMax" step="1" inputmode="numeric" aria-label="Margem desejada" @input="updateDesiredMarginInput" @blur="syncDesiredMarginInput"><span>%</span></label></div><input v-model.number="desiredMargin" type="range" min="0" :max="desiredMarginMax" step="1" aria-label="Margem desejada"><div class="margin-control__scale"><span>0%</span><span>Margem atual: {{Number(actualMargin).toFixed(1)}}%</span><span>{{desiredMarginMax}}%</span></div><small v-if="errors.margin" class="field__error">{{errors.margin}}</small></div>
        <div class="summary-box"><div class="detail-list__row"><span>Total do lote ({{quantity}} un.)</span><strong>{{formatCurrency(batchTotalCost)}}</strong></div><div class="detail-list__row"><span>Lucro estimado do lote</span><strong class="money-positive">{{formatCurrency(batchProfit)}}</strong></div><div v-if="batchQuantity > 1" class="detail-list__row"><span>Lucro estimado por peca</span><strong class="money-positive">{{formatCurrency(estimatedProfit)}}</strong></div><div v-if="feeCost > 0" class="detail-list__row"><span>Taxas e impostos por peca</span><strong>{{formatCurrency(feeCost)}}</strong></div></div>
        <div class="viability" :style="viability.state==='warn'?{borderColor:'#f5a623',color:'#b66808',background:'#fffaf0'}:viability.state==='bad'?{borderColor:'#ef4444',color:'#c12c35',background:'#fff5f5'}:{}"><span class="viability__icon"><UiIcon :name="viability.state==='good'?'check':'alert'"/></span><div><h3>{{viability.title}}</h3><p>{{viability.text}}</p></div></div><button class="btn btn--success btn--wide" style="margin-top:14px" @click="createProduct"><UiIcon name="box"/>Criar produto com esta simulacao</button>
      </aside>
    </div>
  </div>
</template>
